INSERT INTO gochar_bindu_phal (planet,bindu,language,phal_text) VALUES
('Sun',0,'hi','मृत्यु अथवा महान् अपमान।'),
('Sun',1,'hi','रोग तथा चिन्ता।'),
('Sun',2,'hi','पाप कर्म, राज्य द्वारा विरोध व अपमान।'),
('Sun',3,'hi','यात्रा में कष्ट, शारीरिक तथा मानसिक कष्ट।'),
('Sun',4,'hi','आय के साथ ही व्यय, सुख-दुःख दोनों।'),
('Sun',5,'hi','लाभ, सत्संग व विद्या प्राप्ति।'),
('Sun',6,'hi','भाग्य वृद्धि, कीर्ति, कार्य सफलता व वाहन प्राप्ति।'),
('Sun',7,'hi','मान, शौर्य, सत्कीर्ति, कार्य सफलता व वाहन प्राप्ति।'),
('Sun',8,'hi','राजातुल्य मान तथा विशेष राज्यकृपा।'),
('Moon',0,'hi','महा क्लेश, दुःख, मृत्यु तथा निर्धनता।'),
('Moon',1,'hi','अचानक कष्ट तथा भय।'),
('Moon',2,'hi','धनहानि, पत्नी से कलह तथा मित्रों आदि से पृथकता।'),
('Moon',3,'hi','जन साधारण से कलह।'),
('Moon',4,'hi','उदासीन वृत्ति व सुख-दुःख का मिश्रण।'),
('Moon',5,'hi','सुख, शान्ति और धार्मिक उत्साह।'),
('Moon',6,'hi','मन्त्रदीक्षा, उदार व्यक्तियों से मिलन तथा सुख के साधनों की प्राप्ति।'),
('Moon',7,'hi','उत्तम खानपान व रहन-सहन, सुगन्धित द्रव्यों की प्राप्ति व उत्तम सुख सुविधा का जीवन।'),
('Moon',8,'hi','हर प्रकार का सुख व लोकप्रियता तथा उत्तम कीर्ति व प्रभाव।'),
('Mars',0,'hi','आँखों में मूर्च्छा या कष्ट, मृत्यु।'),
('Mars',1,'hi','शास्त्राघात, बुखार तथा चेचक से पीड़ा।'),
('Mars',2,'hi','धन-सम्पत्ति सम्बन्धी लड़ाई।'),
('Mars',3,'hi','शारीरिक क्षीणता, भ्रमण और विपदा।'),
('Mars',4,'hi','सुख-दुःख की सामान्यता।'),
('Mars',5,'hi','न्यायपूर्ण व्यवहार।'),
('Mars',6,'hi','राज्य से बहुत मान सम्मान।'),
('Mars',7,'hi','भाइयों का उत्कर्ष और उनसे लाभ।'),
('Mars',8,'hi','भूमि, मकान आदि की प्राप्ति और शत्रुओं पर विजय।'),
('Mercury',0,'hi','विपुल हानि व मृत्यु।'),
('Mercury',1,'hi','शत्रुओं से गम्भीर कष्ट।'),
('Mercury',2,'hi','वात-पित्त-कफ की विषमता से रोग व दुःख।'),
('Mercury',3,'hi','मानसिक व्यथा।'),
('Mercury',4,'hi','उदासीनता।'),
('Mercury',5,'hi','मित्रों तथा सम्बन्धियों से प्रीति।'),
('Mercury',6,'hi','बुद्धि तीव्र, तथा विजय व महान प्रतिभा।'),
('Mercury',7,'hi','धन बाहुल्य, तीव्र बुद्धि, विद्या और यज्ञीय कार्य।'),
('Mercury',8,'hi','सभी प्रकार का सुख, लोकप्रियता तथा शासन प्राप्ति।'),
('Jupiter',0,'hi','पुत्रादि सन्तान की मृत्यु, कष्ट, धनहीनता व दुर्बुद्धि।'),
('Jupiter',1,'hi','धनहानि।'),
('Jupiter',2,'hi','राज्य प्रकोप तथा बच्चों को कष्ट।'),
('Jupiter',3,'hi','कर्ण रोग, धन में कमी, सुख में कमी व शारीरिक कष्ट।'),
('Jupiter',4,'hi','आर्थिक स्थिति सदा एक जैसी।'),
('Jupiter',5,'hi','कार्यों में सफलता।'),
('Jupiter',6,'hi','सुख-साधनों में विशेष वृद्धि।'),
('Jupiter',7,'hi','सुख शान्ति तथा धन प्राप्ति तथा सन्तान से सुख।'),
('Jupiter',8,'hi','राज्य तथा अधिकार प्राप्ति।'),
('Venus',0,'hi','सब ओर से दुःख तथा आपत्ति।'),
('Venus',1,'hi','कफजनित रोगों का भय तथा रोगिणी पत्नी।'),
('Venus',2,'hi','पत्नी कष्ट तथा रोग।'),
('Venus',3,'hi','मित्र-पड़ौसियों से वैमनस्य।'),
('Venus',4,'hi','मिश्रित फल।'),
('Venus',5,'hi','जनसम्पर्क में वृद्धि, विलास के साधनों की प्राप्ति।'),
('Venus',6,'hi','प्रेमिका प्राप्ति, विलासिता के साधनों की प्रचुर मात्रा में उपलब्धि।'),
('Venus',7,'hi','स्वर्ण तथा रत्न आदि की प्राप्ति व कला से अतीव प्रेम।'),
('Venus',8,'hi','सब प्रकार के भोगों की प्राप्ति, स्वादिष्ट व उत्तम खान-पान, सुन्दर वस्त्र, पौष्टिक फल व सुगन्धित पदार्थों की प्राप्ति।'),
('Saturn',0,'hi','सर्वनाश अथवा मृत्यु।'),
('Saturn',1,'hi','रोग, गन्दगी व अतीव दरिद्रता।'),
('Saturn',2,'hi','कारागार, रोग, क्लेश व दरिद्रता।'),
('Saturn',3,'hi','धनहानि, परिजन हानि, दुःख व स्त्री कष्ट।'),
('Saturn',4,'hi','साधारण सुख-दुःख।'),
('Saturn',5,'hi','धन-धान्य आदि की अच्छी प्राप्ति।'),
('Saturn',6,'hi','निम्न वर्ग के लोगों से मान-सम्मान की प्राप्ति।'),
('Saturn',7,'hi','दास-दासियों व राज्य की प्राप्ति।'),
('Saturn',8,'hi','राज्य में कीर्ति तथा उच्च पद की प्राप्ति।')
INSERT INTO gochar_kaksha_phal (planet,kaksha_lord,kind,language,phal_text) VALUES
('Sun','Saturn','shubh','hi','स्वास्थ्य का उत्तम रहना, छोटे और बड़े सभी से मेल-मिलाप व मित्रवत् व्यवहार, पशु-धन की प्राप्ति, जमीन-जायदाद की प्राप्ति।'),
('Sun','Saturn','rekha','hi','नीच कर्म, रोग, राज्य से वैमनस्य, दृष्टवृत्ति, कृतघ्नता, निम्न श्रेणी के लोगों से वैर।'),
('Sun','Jupiter','shubh','hi','राज्य और राज्य कर्मचारियों से लाभ, ज्ञान वृद्धि, आध्यात्मिक प्रगति, प्रताप वृद्धि, शत्रुओं पर विजय तथा धन वृद्धि।'),
('Sun','Jupiter','rekha','hi','धन की कमी, अज्ञानता के कार्य, धर्म में पाखण्ड, गर्भपात, पित्त के रोग।'),
('Sun','Mars','shubh','hi','स्वर्ण, रत्न, आभूषण आदि की प्राप्ति, पुरुषार्थ के कार्य, विवेकपूर्ण आचरण, न्यायपूर्ण व्यवहार तथा राजपुरुषों से सम्पर्क।'),
('Sun','Mars','rekha','hi','शत्रुओं द्वारा पराजय, शरीर पर चोट, मूर्खता के कार्य, अग्नि से दुर्घटना, आँख में कष्ट।'),
('Sun','Sun','shubh','hi','मान-कीर्ति में वृद्धि, उत्तम स्वास्थ्य, सच्चरित्रता, राज्य कृपा व यज्ञीय कार्य।'),
('Sun','Sun','rekha','hi','रोग, अपमान, राज्य से हानि, निकृष्ट कार्य तथा पराजय।'),
('Sun','Venus','shubh','hi','गौ आदि पशु-धन की प्राप्ति, आध्यात्मिक प्रवृत्ति, स्त्री जाति से लाभ और सुख के साधनों की वृद्धि।'),
('Sun','Venus','rekha','hi','कामुकता, कायरता, धन की कमी, अस्वस्थता, निकृष्ट वातावरण, स्त्री वियोग।'),
('Sun','Mercury','shubh','hi','बुद्धि तीव्रता, विद्या वृद्धि, यज्ञीय कर्मों में प्रवृत्ति, धन बाहुल्य, शास्त्र अध्ययन, शत्रु नाश तथा विजय।'),
('Sun','Mercury','rekha','hi','धोखा देना, विद्या में असफलता, बन्धुजनों से विरोध, पराजय, कायरता।'),
('Sun','Moon','shubh','hi','अन्तर्मुखी वृत्ति, राज्य कृपा, विज्ञान व अनुसन्धान में रुचि, स्त्रियों से लाभ तथा उत्तम स्वास्थ्य।'),
('Sun','Moon','rekha','hi','निर्धनता, गम्भीर चिन्ता, रोग, खाने-पीने की चिन्ता, सामान्य जन से विरोध।'),
('Sun','Lagna','shubh','hi','मान में विशेष वृद्धि, दृढ़ स्वास्थ्य, राज्य कृपा, धन प्राप्ति तथा राजपुरुषों से सम्पर्क।'),
('Sun','Lagna','rekha','hi','स्वास्थ्य हीनता, दुष्प्रवृत्ति, दुःख, धन की कमी, अपमान, राज्य की ओर से चिन्ता।'),
('Moon','Saturn','shubh','hi','लोकप्रियता, निम्न श्रेणी के लोगों से लाभ, विवेकपूर्ण वैराग्य, भाग्य में वृद्धि, धार्मिक विषयों में रुचि, भूमि प्राप्ति।'),
('Moon','Saturn','rekha','hi','दुर्बलता व शारीरिक क्षीणता, धन का अभाव, पराजय, अपमान, पाप-कर्मों में प्रवृत्ति, निम्न श्रेणी के लोगों से हानि, दुःख, मानसिक क्लेश, खाने-पीने की वस्तुओं में कमी।'),
('Moon','Jupiter','shubh','hi','मानसिक शान्ति, घरेलू सुख साधनों का लाभ, राज कृपा प्राप्ति, ज्ञानवर्धक वार्ता में अभिरुचि, धन-ऐश्वर्य वृद्धि।'),
('Moon','Jupiter','rekha','hi','पाखण्ड वृत्ति, धन हानि, बुरे विचार, गुरुजनों का कोप, पुत्रों से नुकसान।'),
('Moon','Mars','shubh','hi','उत्साह वृद्धि, बन्धु वर्ग तथा भाइयों को लाभ, जायदाद प्राप्ति, मित्र सुख, धन वृद्धि।'),
('Moon','Mars','rekha','hi','पाप वृत्ति, भाई-बन्धुओं से वैर, राज्य की ओर से वैमनस्य, शरीरांगों पर चोट, आँख में कष्ट, पित्त रोग, अग्नि सम्बन्धी कार्यों से हानि।'),
('Moon','Sun','shubh','hi','राज्य की ओर से लाभ, मान वृद्धि, धन वृद्धि, महान् व्यक्तियों से सम्पर्क, अध्यात्म में अभिरुचि।'),
('Moon','Sun','rekha','hi','राजपुरुषों से भय, मित्रों द्वारा विरोध, स्वास्थ्य बिगड़ जाये, छाती में कष्ट, धन हानि।'),
('Moon','Venus','shubh','hi','राजपुरुषों का संग, विलास के साधनों की वृद्धि, सत्यप्रियता, स्त्री सम्पर्क में वृद्धि, विनम्रता, विवेक।'),
('Moon','Venus','rekha','hi','कामुकता, दुष्ट स्त्रियों का संग, स्त्री वर्ग से हानि, विलास की वस्तुओं के व्यापार से हानि, मान हानि, जलीय कार्यों से हानि, शत्रु संख्या में वृद्धि।'),
('Moon','Mercury','shubh','hi','विद्या में वृद्धि, स्त्री वर्ग से लाभ, लावण्य रूप प्राप्ति, शास्त्रीय चिंतन मनन, भाषण में पटुता, धन वृद्धि।'),
('Moon','Mercury','rekha','hi','विद्या में असफलता, बुद्धिहीनता, बंधुजनों से विरोध, कायरता, कपड़े आदि में हानि, स्त्री वर्ग से हानि, पराजय।'),
('Moon','Moon','shubh','hi','जीवन स्तर में वृद्धि, मन की शान्ति, स्त्री वश से लाभ, धन बढ़े, उत्तम स्वास्थ्य, सुन्दर स्त्री की प्राप्ति।'),
('Moon','Moon','rekha','hi','धन ह्रास, मानसिक क्लेश, फेफड़ों रोग, स्त्री वर्ग से हानि, निज वर्ग से भी हानि, स्वजन शत्रु हो जायें, जलीय पदार्थों के कार्यों से हानि, खाद्य पदार्थों के व्यापार से हानि।'),
('Moon','Lagna','shubh','hi','धन में विशेष वृद्धि, व्यापार में सक्रियता, प्रसन्नता तथा मानसिक शान्ति, सम्पर्क में वृद्धि, जलीय पदार्थों से लाभ।'),
('Moon','Lagna','rekha','hi','आर्थिक हानि, स्वास्थ्य दोष, दुःख, क्लेश, भय, मतिभ्रम, स्वकीय कार्यों से हानि।'),
('Mars','Saturn','shubh','hi','जमीन-जायदाद प्राप्ति, उत्साह वृद्धि, विजय प्राप्ति, सुख वृद्धि, नौकरों से सुख, बुरे व्यक्ति भी लाभप्रद सिद्ध हों।'),
('Mars','Saturn','rekha','hi','चोरों से डर, बुद्धि ह्रास, शत्रुओं की उत्पत्ति, बन्धुजनों से विरोध, रक्त विकार, दुष्ट जनों की संगत।'),
('Mars','Jupiter','shubh','hi','गुरुजनों की कृपा से शक्ति में वृद्धि, मित्र वृद्धि तथा उनसे लाभ, राज्य कर्मचारियों से लाभ, प्रताप वृद्धि, ऊहापोह शक्ति में अभिवृद्धि, शरीर पुष्टि, बन्धुजनों का उत्कर्ष, विजय प्राप्ति, भूमि लाभ।'),
('Mars','Jupiter','rekha','hi','बड़ों के कोप से शक्ति ह्रास, राज्य कर्मचारियों से वैमनस्य, पित्त रोग व पेट में कष्ट, धन हानि, विद्या का दुरुपयोग।'),
('Mars','Mars','shubh','hi','पुरुषार्थ में विशेष वृद्धि, घर प्राप्ति, सेना के अफसरों से मेल-मिलाप, बन्धुजनों से लाभ, बुद्धि प्रखरता।'),
('Mars','Mars','rekha','hi','भाई-बहन में वैर, स्वजनों से वैमनस्य, पाप में वृत्ति, पराजय, बुद्धि का दुरुपयोग।'),
('Mars','Sun','shubh','hi','पुरुषार्थ से लाभ, राज्य कृपा व मान, कार्य कुशलता, आध्यात्मिक रुचि, बिजली के सामान के व्यापार से लाभ, भूमि प्राप्ति।'),
('Mars','Sun','rekha','hi','राज्य विरोधी कर्म से राज्य विरोध व दण्ड, आँख में कष्ट, पित्त रोग, क्रोध अधिक, पाप प्रवृत्ति में वृद्धि।'),
('Mars','Venus','shubh','hi','सद्व्यवहार में रुचि, कला के प्रति रुझान, स्त्री वर्ग से लाभ, विलास सामग्री के व्यापार से लाभ, प्रमुख व्यक्तियों से सम्पर्क बढ़े, उत्तम स्वास्थ्य।'),
('Mars','Venus','rekha','hi','अन्य स्त्रियों की ओर कामुकता दृष्टि, पाप प्रवृत्ति, स्त्रियों से हानि, शत्रु वृद्धि, स्त्री के कारण कष्ट, बुराई की ओर रुझान तथा बल प्रयोग।'),
('Mars','Mercury','shubh','hi','विद्या प्राप्ति, सूझ-बूझ की उत्तमता, बन्धुजनों से लाभ, कपड़े के कार्य से लाभ, विजय, शास्त्रों में अभिरुचि, व्यापार से लाभ।'),
('Mars','Mercury','rekha','hi','अकस्मात् शत्रु उत्पत्ति, बन्धुजनों का अपमान तथा नाश, धूर्त, बुद्धिहीनता, व्यापार में हानि, पुरुषार्थ करने पर भी विद्याहीनता।'),
('Mars','Moon','shubh','hi','राज्य कर्मचारियों — विशेषतया रक्षा विभाग के लोगों से लाभ, उत्तम राजसी खाद्य पदार्थों की प्राप्ति, भूमि प्राप्ति, उत्साह वृद्धि, कार्य-कुशलता, बन्धु वर्ग की वृद्धि, मित्रों से लाभ।'),
('Mars','Moon','rekha','hi','मित्रों से हानि, व्यय वृद्धि, पाप कर्मों में प्रवृत्ति, आँखों में कष्ट, धन ह्रास व कामुकता में वृद्धि।'),
('Mars','Lagna','shubh','hi','जमीन-जायदाद के क्रय-विक्रय से लाभ, बन्धु जनों से लाभ, अग्नि सम्बन्धी कार्यों से लाभ, पुरुषार्थ में विशेष वृद्धि, संकल्प शक्ति, प्रताप में वृद्धि।'),
('Mars','Lagna','rekha','hi','क्रूर कर्मों में प्रवृत्ति, झगड़े में पराजय, गंभीर शारीरिक कष्ट, भय, धन हानि, बिजली के कार्यों से हानि।'),
('Mercury','Saturn','shubh','hi','मित्रों व निम्न श्रेणी के लोगों से लाभ, आचार शुद्धि, गूढ़ विचार शक्ति, लोहे आदि धातु के कार्यों से लाभ।'),
('Mercury','Saturn','rekha','hi','बुद्धि का पाप की दिशा में प्रयोग, विचाराधीन भाव के गुणों की मन्दता, बन्धुजनों से विरोध, बुद्धि मन्दता, विद्या में असफलता।'),
('Mercury','Jupiter','shubh','hi','ज्ञान में अभिवृद्धि, परोपकार व शास्त्र अध्ययन में विशेष रुचि, तीर्थ-यात्रा, यज्ञ-कर्म, शारीरिक तेज में वृद्धि, विद्या प्राप्ति।'),
('Mercury','Jupiter','rekha','hi','पाखण्ड लिप्सता, राज्य दण्ड से व्यापार में हानि, गुरुजनों से मतभेद, आचार-विचार में बिगाड़, स्वार्थपरकता।'),
('Mercury','Mars','shubh','hi','तर्क शक्ति में विशेष वृद्धि, लाल वस्तुओं के व्यापार से लाभ, राज्य के क्षेत्र में कुशलता का प्रदर्शन, विजय, शौर्य वृद्धि, शत्रु पराजय, शुभ कर्मों में रुचि, युक्ति-युक्त वाणी का प्रयोग।'),
('Mercury','Mars','rekha','hi','व्यापार में अचानक हानि, पाप भावना में वृद्धि, सौन्दर्य में ह्रास, अन्तड़ियों का ऑपरेशन, राज्य कर्मचारियों से कष्ट।'),
('Mercury','Sun','shubh','hi','आध्यात्मिक प्रगति, विद्या वृद्धि, यज्ञीय कर्मों में प्रवृत्ति, बन्धुजनों से प्रेम, बुद्धि कुशाग्रता व लेखों में गहनता।'),
('Mercury','Sun','rekha','hi','बुद्धि ह्रास, विद्या में असफलता, नम्रता का अभाव, पाखण्ड, व्यापार में हानि, स्वार्थपरकता।'),
('Mercury','Venus','shubh','hi','विलासिता के साधनों की उपलब्धि, स्त्री वर्ग से सद्भावना, विद्वज्जनों से प्रेम, सत्यप्रियता में अभिवृद्धि, वाणी में मिठास और सांस्कृतिक अभिरुचि।'),
('Mercury','Venus','rekha','hi','स्त्रीवर्ग से हानि, गन्दी वस्तुओं से प्यार, झूठ में प्रवृत्ति, बुद्धि का दुष्प्रयोग, सुसंस्कृत विचारों से दूरी।'),
('Mercury','Mercury','shubh','hi','विशेष बुद्धि उपयोग, व्यापार वृद्धि, लेखन कला में रुचि, बन्धुजनों से लाभ, शत्रुओं पर विजय, खाद्य पदार्थों में वृद्धि, कपड़े के व्यापारियों से लाभ, वाद्य कला व ज्योतिष विद्या में रुचि।'),
('Mercury','Mercury','rekha','hi','बुद्धि मन्दता, विद्या हानि, नम्रता का अभाव, धन की कमी, व्यापार में हानि, स्वार्थ की प्रवृत्ति व पराजय।'),
('Mercury','Moon','shubh','hi','व्यापार से लाभ, सद्बुद्धि प्राप्ति, यज्ञीय कर्मों में प्रवृत्ति, स्त्री वर्ग से लाभ, शहरी जनता से लाभ, रूप लावण्य में अभिवृद्धि, कपड़े के व्यापार से लाभ।'),
('Mercury','Moon','rekha','hi','शत्रु वृद्धि, परोपकार भावना में कमी, सन्तान को भाग्यहीनता, उल्टी बुद्धि, व्यापार में हानि, चिन्ता वृद्धि, सिरदर्द।'),
('Mercury','Lagna','shubh','hi','मान वृद्धि, आध्यात्मिकता में रुचि, यज्ञीय कर्मों में प्रवृत्ति, धन-धान्य वृद्धि, सन्तान को विशेष लाभ।'),
('Mercury','Lagna','rekha','hi','चर्म रोग, जुआ आदि व्यसन, धन का अभाव, अचानक सिर में कष्ट।'),
('Jupiter','Saturn','shubh','hi','दार्शनिक ज्ञान प्राप्ति, जमीन प्राप्ति, निम्न श्रेणी के लोगों से लाभ, शुद्ध आचार-विचार में लगाव, सुख वृद्धि, जन-साधारण से अधिक सम्पर्क।'),
('Jupiter','Saturn','rekha','hi','लोभ के कारण धन हानि, दुःख वृद्धि, आचार-विचार में त्रुटि, निम्न वर्ग के व्यक्तियों द्वारा राज्य को हानि।'),
('Jupiter','Jupiter','shubh','hi','गृहस्थ सुखों में विशेष वृद्धि, धर्म और ज्ञान में अभिरुचि, राज्य की ओर से लाभ, धन वृद्धि, सत्कीर्ति, गुरुजनों से कृपा प्राप्ति।'),
('Jupiter','Jupiter','rekha','hi','दुराचारी वृत्ति, दुःख प्राप्ति, गुरुजनों से विरोध, ज्ञान के दुरुपयोग से हानि, सन्तान को कष्ट।'),
('Jupiter','Mars','shubh','hi','मित्रों के पुरुषार्थ से धन प्राप्ति, उत्साह में विशेष वृद्धि, पदोन्नति, जातक को भ्रातृ वर्ग से लाभ तथा भ्रातृ वर्ग को भी जातक से लाभ, सदाचार में रुचि।'),
('Jupiter','Mars','rekha','hi','मित्रों द्वारा धन नाश, शारीरिक आघात, दुःख प्राप्ति, सन्तान कष्ट, राज्य से विरोध, दुष्कर्मों में प्रवृत्ति, मित्रों से हानि, गुरुजनों से विरोध।'),
('Jupiter','Sun','shubh','hi','राज्यकृपा अथवा राज्य प्राप्ति, राज्य कर्मचारियों एवं अधिकारियों से सुख, आध्यात्मिकता में रुचि, ज्ञान में सूक्ष्मता, स्वर्ण आदि की प्राप्ति, मान वृद्धि, उत्तम स्वास्थ्य, शुभदर्शनों का सौभाग्य, धन वृद्धि।'),
('Jupiter','Sun','rekha','hi','राज्य द्वारा धन हानि, राज कर्मचारियों से विरोध, मित्रों से वैमनस्य, धन की कमी, पेट में कष्ट, पुत्र से वियोग, गर्भपात।'),
('Jupiter','Venus','shubh','hi','गुरुजनों से विशेष लाभ, कानून आदि के ज्ञान में वृद्धि, सत्याचरण, सदाचारी स्त्रियों से लाभ, मंत्रणा शक्ति में वृद्धि, सन्तान प्राप्ति, महात्मा जनों से सम्पर्क, व्यावहारिक सूझबूझ व वाहन प्राप्ति।'),
('Jupiter','Venus','rekha','hi','शत्रु उत्पत्ति, छिपकर पाप रत होने की प्रवृत्ति, स्त्री वर्ग से हानि, शत्रुओं से धन हानि, झूठ से अधिक लगाव।'),
('Jupiter','Mercury','shubh','hi','हर प्रकार के ज्ञान-विज्ञान में रुचि, धन वृद्धि, सुख वृद्धि, विद्या में उन्नति, देह-सौख्य प्राप्ति, उपदेशादि देने की योग्यता, गुरुजनों का आदर।'),
('Jupiter','Mercury','rekha','hi','ज्ञान का दुरुपयोग, निष्फल वार्तालाप, पाचन-शक्ति का ह्रास, दूसरों से कपटपूर्ण व्यवहार, स्वार्थ सिद्धि व अधार्मिकता की ओर रुझान।'),
('Jupiter','Moon','shubh','hi','उत्तम स्वास्थ्य प्राप्ति, मन में शान्ति, मित्रों से लाभ, धन वृद्धि, गुरुजनों तथा ईश्वर में आस्था, स्मरण शक्ति की उत्तमता।'),
('Jupiter','Moon','rekha','hi','धन हानि, मित्रों से विरोध, कफ दोष, कुपित होने से कष्ट, दुःख प्राप्ति, मानसिक अशान्ति, जनता द्वारा धन नाश।'),
('Jupiter','Lagna','shubh','hi','सदाचारी व्यवहार, उत्तम स्वास्थ्य, मान में वृद्धि, राज्य की ओर से कृपा पात्रता, शास्त्र आदि के ज्ञान तथा सुख में वृद्धि व पठन-पाठन से लाभ।'),
('Jupiter','Lagna','rekha','hi','पाखण्ड में वृत्ति, अपने ही पाँव पर कुल्हाड़ी मारना, अपयश, मित्रों से दुःख, मित्रों द्वारा धन नाश।'),
('Venus','Saturn','shubh','hi','सदाचार प्राप्ति, स्त्री वर्ग से लाभ, मित्रों से लाभ, क्षेत्र प्राप्ति, सुख वृद्धि, निम्न श्रेणी के व्यक्तियों से लाभ।'),
('Venus','Saturn','rekha','hi','पाप कर्मों में प्रवृत्ति, वीर्य दोष, मूत्रेन्द्रिय में कष्ट, सन्तान का ह्रास, स्त्री से पृथकता, झूठ-कपट के व्यवहार में वृद्धि।'),
('Venus','Jupiter','shubh','hi','उत्तम मन्त्रणा शक्ति प्राप्ति, विशेष धन वृद्धि, सद्व्यवहार में रुचि, धार्मिक प्रवृत्ति, मानसिक शान्ति व आत्म-संयम प्राप्ति, ज्ञान वृद्धि।'),
('Venus','Jupiter','rekha','hi','शत्रु उत्पत्ति, विद्वानों से विरोध, राज्य कर्मचारियों से वैमनस्य, अपनी जाति के व्यक्तियों द्वारा विरोध, पुत्रों से पृथकता।'),
('Venus','Mars','shubh','hi','अति उत्साह प्राप्ति, बुद्धि प्रखरता, सत्य में रुचि, भ्रातृजनों से प्रेम, भाइयों को सुख वृद्धि, ब्राह्मणों की सेवा।'),
('Venus','Mars','rekha','hi','पाप कर्मों में प्रवृत्ति, कामुकता, आँखों में कष्ट, स्त्री को कष्ट, वाहन नाश, दण्ड अथवा चोट से कष्ट।'),
('Venus','Sun','shubh','hi','उत्तम स्वास्थ्य, शत्रुओं से भी लाभ, आत्मिक शान्ति, राज-पुरुषों से मिलाप, सदाचरण।'),
('Venus','Sun','rekha','hi','राज्य की ओर से विरोध तथा दण्ड, आँख में कष्ट, पशु धन का नाश, धन में कमी, भोग सामग्री में कमी, वस्त्र तथा आभूषणों का नाश, मूत्रेन्द्रिय में कष्ट।'),
('Venus','Venus','shubh','hi','सन्तान प्राप्ति, सुन्दर वाहन प्राप्ति, सदाचरण, पशु-धन वृद्धि, स्त्री वर्ग से लाभ, भोग विलास के साधनों में वृद्धि, मन्त्रणा शक्ति का प्रयोग।'),
('Venus','Venus','rekha','hi','दुष्टजनों का संग, गन्दे वातावरण में निवास, मुखाकृति में विकृति, सुख-साधनों का ह्रास, संतान को कष्ट, उत्साहहीनता।'),
('Venus','Mercury','shubh','hi','मित्र प्राप्ति, सांस्कृतिक कार्यरत होना, स्त्री वर्ग से लाभ, विद्वानों से सम्पर्क, सत्यप्रियता, मन्त्रणा शक्ति, मुख पर लावण्य प्राप्ति, वाणी चातुर्य।'),
('Venus','Mercury','rekha','hi','मित्रों से हानि, लेखन-कला में हानि, लेखक गणों से विरोध, विद्वानों से वैमनस्य, मन्त्रणा की व्यर्थता।'),
('Venus','Moon','shubh','hi','कामुकता वृद्धि, स्त्री वर्ग से लाभ, यश, धन में वृद्धि, मन में शान्ति, सुन्दर खाद्य-पदार्थों की उपलब्धि, जन-साधारण से अधिक सम्पर्क।'),
('Venus','Moon','rekha','hi','स्त्री वर्ग से हानि, मानसिक व्यथा, कला के कार्यों में उदासीनता, कामुकता वृद्धि, वस्त्रादि के व्यापार से हानि, पत्नी से कष्ट।'),
('Venus','Lagna','shubh','hi','संगीत आदि कला से लाभ, आकृति में आकर्षकता, यश वृद्धि, ब्राह्मणों से प्रेम।'),
('Venus','Lagna','rekha','hi','सन्तान तथा पत्नी से विरोध, संगीत तथा आमोद-प्रमोद के कार्यों में हानि, कामुकता में रति, असत्य व्यवहार, सुख का ह्रास, स्त्री से वैमनस्य।'),
('Saturn','Saturn','shubh','hi','धन तथा भूमि में वृद्धि, जन संपर्क में वृद्धि, निम्न श्रेणी के व्यक्तियों से लाभ, सदाचार में वृत्ति, स्त्री वर्ग से लाभ, धैर्य सम्पन्नता।'),
('Saturn','Saturn','rekha','hi','पाप कर्मों में रति, दुःख प्राप्ति, भूमि नाश, भृत्यों से कलह, सामान्य जन द्वारा विरोध।'),
('Saturn','Jupiter','shubh','hi','क्षेत्र प्राप्ति, सदाचार में वृद्धि, जन साधारण में मान-सम्मान, सुख व उत्साह में वृद्धि।'),
('Saturn','Jupiter','rekha','hi','पाप प्रवृत्ति, आचार-विचार में बिगाड़ आ जाना, पुत्रों से विरोध, राज्य से कष्ट, दुःख की उत्पत्ति, आय में कमी।'),
('Saturn','Mars','shubh','hi','पशुधन व सम्मान में वृद्धि, शत्रुओं से लाभ, मकान-जायदाद प्राप्ति, प्रताप वृद्धि, भाइयों में सद्व्यवहार, कारखाने आदि से लाभ।'),
('Saturn','Mars','rekha','hi','चोरी आदि से हानि, पाप में अधिक प्रवृत्ति, सिर दर्द, चोट आदि से कष्ट, भ्रातृ वर्ग से विरोध, भूमि नाश, पुरुषार्थहीनता, शत्रुओं द्वारा धन नाश।'),
('Saturn','Sun','shubh','hi','राज्य से लाभ, पूंजीपतियों से लाभ, पदोन्नति, शत्रुओं से लाभ, सुख वृद्धि, विचारों में गम्भीरता।'),
('Saturn','Sun','rekha','hi','राज्य से चिन्ता, शत्रुओं द्वारा दुःख का भय, आँखों में कष्ट, भृत्यों द्वारा अवज्ञा, वृत्ति का त्याग, रोग।'),
('Saturn','Venus','shubh','hi','मित्रों से लाभ, स्त्री वर्ग से लाभ, पशुधन में विशेष वृद्धि, भृत्य वर्ग से लाभ, मित्र संख्या में वृद्धि।'),
('Saturn','Venus','rekha','hi','मित्रों से बिगाड़, गन्दी वस्तुओं से प्यार, पत्नी से वैमनस्य, स्त्री वर्ग से हानि, मूत्रेन्द्रिय का रोग।'),
('Saturn','Mercury','shubh','hi','जमीन-जायदाद की प्राप्ति, मित्र संख्या में वृद्धि, स्त्री वर्ग से लाभ, शास्त्र अध्ययन में रुचि, सदाचार प्राप्ति, भृत्यों से लाभ।'),
('Saturn','Mercury','rekha','hi','विद्या में असफलता, विद्वानों से विरोध, बुद्धि की मन्दता, साहित्य में अरुचि, सिरदर्द, चपलता का ह्रास, उन्माद।'),
('Saturn','Moon','shubh','hi','शत्रुओं द्वारा भी प्रेम का व्यवहार, लोहे-मशीनरी आदि के कार्यों से लाभ, सुख व भूमि की प्राप्ति, स्त्री वर्ग से लाभ, विवेक व वैराग्य की प्राप्ति।'),
('Saturn','Moon','rekha','hi','जड़ता, धन की कमी, स्त्री वर्ग से हानि, खाद्य पदार्थों की कमी, लम्बी बीमारी, आँखों में कष्ट, सीने में दर्द।'),
('Saturn','Lagna','shubh','hi','सुख व आयु वृद्धि, रोग निवृत्ति, भृत्यों से सेवा का लाभ, इंजीनियरिंग आदि कार्यों से लाभ।'),
('Saturn','Lagna','rekha','hi','पाप में वृत्ति, वंचना में रुचि, कामुकता में वृद्धि, स्त्री वर्ग से हानि, मानसिक क्लेश, धन हानि, मान हानि व स्थान परिवर्तन।')
INSERT INTO gochar_sav_hint (band,language,hint_text) VALUES
('28 से अधिक','hi','उस भाव सम्बन्धी शुभ फल; जितने अधिक उतने ही शुभ।'),
('28 से कम','hi','उस भाव सम्बन्धी अशुभ फल; जितने कम उतने ही अशुभ।'),
('विशेष','hi','9, 10, 11वें भाव में 28 से अधिक होने पर ही जीवन सफल होता है।')
