-- =============================================================================
-- Auto Business — Gochar Ashtakavarga phal (migration 021)
-- Update: bindu-count phal (Part 1), Kaksha phal (Part 2), SAV hints (Part 3).
-- Additive Gochar categories — does NOT change Layer 1/3/4 texts.
-- Source: docs/Gochar_Ashtakavarga_Phal.md (Gochar Vichar Ch.7).
-- =============================================================================
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS gochar_bindu_phal (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    planet VARCHAR(12) NOT NULL, bindu TINYINT NOT NULL,
    language VARCHAR(8) NOT NULL DEFAULT 'hi', phal_text TEXT NOT NULL,
    updated_by_staff_id BIGINT UNSIGNED NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id), UNIQUE KEY uq_gbp (planet, bindu, language)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE phal_text=VALUES(phal_text);

CREATE TABLE IF NOT EXISTS gochar_kaksha_phal (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    planet VARCHAR(12) NOT NULL, kaksha_lord VARCHAR(12) NOT NULL, kind VARCHAR(8) NOT NULL,
    language VARCHAR(8) NOT NULL DEFAULT 'hi', phal_text TEXT NOT NULL,
    updated_by_staff_id BIGINT UNSIGNED NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id), UNIQUE KEY uq_gkp (planet, kaksha_lord, kind, language)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE phal_text=VALUES(phal_text);

CREATE TABLE IF NOT EXISTS gochar_sav_hint (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, band VARCHAR(24) NOT NULL,
    language VARCHAR(8) NOT NULL DEFAULT 'hi', hint_text TEXT NOT NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id), UNIQUE KEY uq_gsh (band, language)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE hint_text=VALUES(hint_text);

ON DUPLICATE KEY UPDATE cfg_value=cfg_value;
-- End of migration 021.
